import React, { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import api from "../../api/axiosConfig";
import { jsPDF } from "jspdf";
import autoTable from 'jspdf-autotable';
import {
    BsPersonBadge, BsSearch, BsShieldLock,
    BsEnvelope, BsTelephone, BsDownload,
    BsGrid, BsListUl, BsTrash, BsEye, BsExclamationTriangleFill,
} from 'react-icons/bs';
import {
    PieChart, Pie, Cell, ResponsiveContainer
} from "recharts";


// --- CONFIG ---
const IMAGE_BASE_URL = "http://localhost:8081/user/uploads";
const DEFAULT_AVATAR = "https://ui-avatars.com/api/?background=000&color=fff&bold=true&size=128";
const MASTER_ADMIN_KEY = "NEXUS-2025";

// Place this OUTSIDE your component function
const LOGO_BASE64 ="data:image/png;base64,";


function DisplayUsers() {
    const navigate = useNavigate();

    // 1. GET THE ROLE
    const userRole = localStorage.getItem('userRole');
    const isAdmin = userRole === 'ADMIN';

    // --- STATE ---
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const [viewMode, setViewMode] = useState('grid'); // 'grid' or 'list'
    const [selectedUser, setSelectedUser] = useState(null); // For Modal
    const [filterRole, setFilterRole] = useState("ALL"); // 'ALL', 'ADMIN', 'USER'

    // --- NEW SECURITY STATE ---
    const [deleteTarget, setDeleteTarget] = useState(null); // Who are we deleting?
    const [securityCode, setSecurityCode] = useState("");   // Input for key
    const [securityError, setSecurityError] = useState(""); // Error message

    // --- NEW: ANIMATION STATE ---
    const [isNavigating, setIsNavigating] = useState(false);

    // --- NEW: UNIVERSAL TRANSITION HANDLER ---
    const handleTransition = (target) => {
        setIsNavigating(true); // 1. Start Animation
        
        // 2. Wait 1 second
        setTimeout(() => {
            if (typeof target === 'string') {
                navigate(target); // If text, go to that URL (Back Button)
            } else if (typeof target === 'function') {
                target(); // If function, run it (Pagination)
                setIsNavigating(false); // Stop animation since we aren't leaving the page
            }
        }, 1000); 
    };

    // Pagination
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    useEffect(() => {
        loadUsers();
    }, []);

    const loadUsers = async () => {
        setLoading(true);
        try {
            const result = await api.get("/users");
            setUsers(result.data);
        } catch (error) {
            console.error("Error loading users:", error);
        } finally {
            setLoading(false);
        }
    }

    // --- ANALYTICS & LOGIC ---
    const stats = useMemo(() => {
        const total = users.length;
        const admins = users.filter(u => (u.type || '').toLowerCase() === 'admin').length;
        const regular = total - admins;

        // Data for Radial Chart
        const roleData = [
            { name: 'Administrators', value: admins },
            { name: 'Standard Users', value: regular }
        ];

        return { total, admins, regular, roleData };
    }, [users]);

    // --- FILTERING ---
    const filteredUsers = users.filter(user => {
        const matchesSearch = (user.firstname + " " + user.lastname).toLowerCase().includes(searchQuery.toLowerCase()) ||
            user.email.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesRole = filterRole === "ALL" ? true : (user.type || 'user').toUpperCase() === filterRole;
        return matchesSearch && matchesRole;
    });

    const paginatedUsers = filteredUsers.slice(
        (currentPage - 1) * itemsPerPage,
        currentPage * itemsPerPage
    );
    const totalPages = Math.ceil(filteredUsers.length / itemsPerPage);

    // --- ACTIONS ---
    
    // 1. OPEN SECURITY MODAL (Instead of deleting immediately)
    const initiateDelete = (user) => {
        setDeleteTarget(user);
        setSecurityCode("");
        setSecurityError("");
    };

    // 2. CONFIRM AND EXECUTE (Actual Deletion)
    const confirmDelete = async () => {
        if (securityCode !== MASTER_ADMIN_KEY) {
            setSecurityError("❌ ACCESS DENIED: Invalid Security Clearance Code.");
            return;
        }

        try {
            await api.delete(`/user/${deleteTarget.id}`);
            loadUsers(); // Refresh list
            setDeleteTarget(null); // Close modal
            alert("User profile successfully terminated.");
        } catch (error) {
            setSecurityError("System Error: Deletion failed via API.");
        }
    };

    const generatePDF = () => {
        const doc = new jsPDF();
        const pageWidth = doc.internal.pageSize.width;
        const pageHeight = doc.internal.pageSize.height;

        // --- THEME COLORS ---
        const colors = {
            black: '#000000',
            darkGrey: '#2c2c2c',
            lightGrey: '#e5e5e5',
            white: '#ffffff'
        };

        // --- 1. HEADER: "DOSSIER STYLE" ---
        // Draw a massive black header
        doc.setFillColor(colors.black);
        doc.rect(0, 0, pageWidth, 70, 'F'); 

        // Logo (Top Center)
        const logoSize = 16;
        const logoX = (pageWidth - logoSize) / 2;
        try {
            doc.addImage(LOGO_BASE64, 'PNG', logoX, 10, logoSize, logoSize); 
        } catch (e) { console.warn("Logo error", e); }

        // Title: PERSONNEL DIRECTORY (Serif, Wide Tracking)
        doc.setFont("times", "roman");
        doc.setFontSize(26);
        doc.setTextColor(colors.white);
        doc.text("PERSONNEL DIRECTORY", pageWidth / 2, 40, { align: "center" });

        // Subtitle with Dynamic Date
        doc.setFont("helvetica", "bold");
        doc.setFontSize(8);
        doc.setTextColor(180, 180, 180);
        const dateStr = new Date().toLocaleDateString().toUpperCase();
        
        // Manual Center Calculation for spacing
        const subtitle = `AUTHORIZED ACCESS REGISTRY  |  ${dateStr}`;
        const textWidth = doc.getTextWidth(subtitle);
        const startX = (pageWidth - (textWidth + (subtitle.length * 0.5))) / 2; // approx spacing adjustment
        doc.text(subtitle, startX, 50, { charSpace: 1.5 });

        // --- 2. EXECUTIVE SUMMARY (Split Layout) ---
        let startY = 85;

        // LEFT SIDE: Description
        doc.setFont("times", "bold");
        doc.setFontSize(14);
        doc.setTextColor(colors.black);
        doc.text("Workforce Status", 14, startY);

        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(80, 80, 80);
        const descText = "This document contains confidential records of all registered personnel. Access levels are strictly enforced based on the roles defined below.";
        doc.text(descText, 14, startY + 8, { maxWidth: 90 }); // Constrain width to left side

        // RIGHT SIDE: Stats Grid (Calculated)
        const totalStaff = users.length;
        const admins = users.filter(u => (u.type || "").toUpperCase() === 'ADMIN').length;
        const activeUsers = totalStaff - admins;

        autoTable(doc, {
            startY: startY - 5, // Align top with the title
            margin: { left: 110 }, // Push to right side
            theme: 'grid',
            head: [['TOTAL HEADCOUNT', 'ADMINISTRATORS', 'STANDARD STAFF']],
            body: [[totalStaff.toString(), admins.toString(), activeUsers.toString()]],
            styles: {
                font: 'helvetica',
                fontSize: 10,
                halign: 'center',
                cellPadding: 8,
                lineColor: [0, 0, 0],
                lineWidth: 0.1,
                textColor: colors.black
            },
            headStyles: {
                fillColor: [255, 255, 255],
                textColor: [100, 100, 100],
                fontStyle: 'bold',
                fontSize: 7,
                halign: 'center',
                lineColor: [0, 0, 0],
                lineWidth: 0.1
            },
            bodyStyles: {
                fillColor: [255, 255, 255],
                fontStyle: 'bold',
                fontSize: 12
            }
        });

        // --- 3. PERSONNEL TABLE ---
        // Helper to fix roles
        const normalizeRole = (role) => (role || "").toString().toUpperCase().trim();

        const tableRows = users.map(u => {
            const role = normalizeRole(u.type);
            const displayRole = role === 'ADMIN' ? 'ADMINISTRATOR' : 'User'; // Title Case for user
            
            return [
                u.userid || u.id, // Prefer string ID if available
                `${u.firstname} ${u.lastname}`,
                u.email,
                displayRole, 
                u.phone || '-',
                (u.address || '-').substring(0, 25) // Truncate long addresses
            ];
        });

        autoTable(doc, {
            startY: doc.lastAutoTable.finalY + 20, // Start below the summary
            head: [['UID', 'FULL NAME', 'EMAIL ADDRESS', 'ACCESS ROLE', 'CONTACT', 'LOCATION']],
            body: tableRows,
            theme: 'plain',
            styles: {
                fontSize: 8,
                cellPadding: 6,
                textColor: colors.darkGrey,
                valign: 'middle',
                lineColor: [230, 230, 230],
                lineWidth: 0.1, // Subtle borders for rows
            },
            headStyles: {
                fillColor: [0, 0, 0], // Solid Black Header
                textColor: [255, 255, 255],
                fontStyle: 'bold',
                halign: 'left',
                textTransform: 'uppercase'
            },
            columnStyles: {
                0: { cellWidth: 25, font: 'courier' }, // Monospace ID
                1: { cellWidth: 35, fontStyle: 'bold' }, // Name Bold
                2: { cellWidth: 40 },
                3: { cellWidth: 30 },
                4: { cellWidth: 30 },
                5: { cellWidth: 'auto' }
            },
            alternateRowStyles: {
                fillColor: [250, 250, 250] // Very light zebra stripes
            },
            // Custom Styling: Make ADMINs stand out
            didParseCell: function(data) {
                if (data.section === 'body' && data.column.index === 3) {
                    if (data.cell.raw === 'ADMINISTRATOR') {
                        data.cell.styles.fontStyle = 'bold';
                        data.cell.styles.textColor = [0, 0, 0]; // Pure Black
                    } else {
                        data.cell.styles.textColor = [120, 120, 120]; // Grey for users
                    }
                }
            }
        });

        // --- 4. FOOTER ---
        const pageCount = doc.internal.getNumberOfPages();
        for(let i = 1; i <= pageCount; i++) {
            doc.setPage(i);
            
            // Black Footer Bar
            doc.setFillColor(0, 0, 0);
            doc.rect(0, pageHeight - 12, pageWidth, 12, 'F');
            
            doc.setFont("helvetica", "normal");
            doc.setFontSize(7);
            doc.setTextColor(255, 255, 255);
            
            doc.text('CONFIDENTIAL PERSONNEL RECORD • AUTHORIZED USE ONLY', 14, pageHeight - 5);
            doc.text(`PAGE ${i} OF ${pageCount}`, pageWidth - 14, pageHeight - 5, { align: 'right' });
        }

        doc.save("Nexus_Personnel_Registry.pdf");
    };

    // Helper for Images
    const getAvatar = (user) => {
        if (user.userimg) return `${IMAGE_BASE_URL}/${user.userimg}`;
        return `${DEFAULT_AVATAR}&name=${user.firstname}+${user.lastname}`;
    }

    // --- STYLES (MONOCHROME PREMIUM - ID CARD THEME) ---
    const styles = {
        wrapper: { backgroundColor: '#f4f4f5', minHeight: '100vh', fontFamily: "'Inter', sans-serif", color: '#18181b' },

        // Distinct Hero: Split layout with large numbers
        hero: {
            background: '#fff', padding: '3rem 2rem', borderBottom: '1px solid #e4e4e7',
            display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap'
        },
        heroTitle: { fontSize: '2.5rem', fontWeight: '800', letterSpacing: '-1.5px', margin: 0, lineHeight: 1 },
        heroSubtitle: { color: '#71717a', fontSize: '0.9rem', letterSpacing: '1px', textTransform: 'uppercase', marginTop: '5px' },

        // Distinct Stats: Minimalist vertical blocks
        statBlock: { borderLeft: '3px solid #000', paddingLeft: '1rem', minWidth: '150px' },
        statNum: { fontSize: '2rem', fontWeight: '700', lineHeight: 1 },
        statLabel: { fontSize: '0.75rem', textTransform: 'uppercase', color: '#71717a', fontWeight: '600' },

        // Toolbar
        toolbar: { padding: '1.5rem 2rem', display: 'flex', gap: '1rem', flexWrap: 'wrap', alignItems: 'center' },
        searchContainer: { flex: 1, position: 'relative', maxWidth: '400px' },
        searchInput: {
            width: '100%', padding: '12px 15px 12px 40px', border: '1px solid #d4d4d8',
            borderRadius: '0', background: '#fff', fontSize: '0.9rem'
        },
        searchIcon: { position: 'absolute', left: '15px', top: '50%', transform: 'translateY(-50%)', color: '#a1a1aa' },

        // ID CARD (The "Difference")
        idCard: {
            background: '#fff', border: '1px solid #e4e4e7', overflow: 'hidden',
            position: 'relative', height: '100%', transition: 'all 0.3s ease',
            display: 'flex', flexDirection: 'column', alignItems: 'center',
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)'
        },
        idHeader: { width: '100%', height: '80px', background: '#18181b', position: 'relative' },
        idAvatarContainer: {
            width: '90px', height: '90px', borderRadius: '50%', background: '#fff',
            padding: '4px', marginTop: '-45px', zIndex: 2, position: 'relative'
        },
        idAvatar: { width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover', background: '#f4f4f5' },
        idBody: { padding: '1rem 1.5rem 1.5rem', textAlign: 'center', width: '100%' },
        idName: { fontSize: '1.1rem', fontWeight: '700', marginBottom: '4px' },
        idRole: {
            fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '1px',
            padding: '4px 10px', background: '#f4f4f5', borderRadius: '4px', display: 'inline-block', marginBottom: '1rem'
        },
        idMeta: { fontSize: '0.85rem', color: '#52525b', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px', marginBottom: '4px' },
        idActions: {
            borderTop: '1px solid #f4f4f5', width: '100%', padding: '10px',
            display: 'flex', justifyContent: 'space-around', background: '#fafafa'
        },
        actionIcon: { cursor: 'pointer', color: '#52525b', fontSize: '1.1rem', transition: 'color 0.2s' },

        // List View Strip
        listRow: {
            background: '#fff', padding: '1rem', marginBottom: '0.75rem', border: '1px solid #e4e4e7',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between', transition: 'transform 0.2s'
        },
        backButton: {
            background: 'none',
            border: 'none',
            color: '#6c757d',
            textTransform: 'uppercase',
            fontSize: '1rem',
            fontWeight: 'bold',
            letterSpacing: '1px',
            //padding: '10px 20px',
            //marginBottom: '2rem',
            //marginTop: '1.6rem',
            //padding: 0,
            cursor: 'pointer'
        },

        // Modal (The Dossier)
        modalOverlay: { position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 2000, display: 'flex', justifyContent: 'center', alignItems: 'center', backdropFilter: 'blur(4px)' },
        dossier: { width: '800px', height: '500px', background: '#fff', display: 'flex', boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)', overflow: 'hidden' },
        dossierSidebar: { width: '30%', background: '#18181b', color: '#fff', padding: '2rem', display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center' },
        dossierContent: { width: '70%', padding: '2.5rem', overflowY: 'auto' },

        // SECURITY MODAL STYLES (PREMIUM)
        securityBox: { width: '500px', background: '#fff', padding: '0', border: '1px solid #dc2626', boxShadow: '0 0 50px rgba(220, 38, 38, 0.2)' },
        securityHeader: { background: '#dc2626', color: '#fff', padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem' },
        securityBody: { padding: '2rem' },
        securityInput: { width: '100%', padding: '12px', border: '2px solid #e5e5e5', borderRadius: '0', fontSize: '1rem', textAlign: 'center', letterSpacing: '3px', fontWeight: 'bold' },

        // NEW: Loader Overlay Styles
        loaderOverlay: {
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.8)', // White with opacity
            backdropFilter: 'blur(8px)', // Frosted Glass
            zIndex: 10000,
            display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column'
        }
    };

    // --- CHART CONFIG ---
    const CHART_COLORS = ['#18181b', '#a1a1aa']; // Black & Gray

    if (loading) return <div className="d-flex justify-content-center align-items-center vh-100 bg-white"><div className="spinner-border text-dark"></div></div>;

    return (
        <div style={styles.wrapper}>
            
            {/* --- INJECT CSS ANIMATION --- */}
            <style>{`
                .wave-loader {
                    display: flex;
                    justify-content: center;
                    align-items: center;
                }
                .wave-dot {
                    width: 15px;
                    height: 15px;
                    margin: 0 5px;
                    background-color: #000; /* Black dots */
                    border-radius: 50%;
                    animation: wave 1.2s infinite ease-in-out both;
                }
                .wave-dot:nth-child(1) { animation-delay: -1.1s; }
                .wave-dot:nth-child(2) { animation-delay: -1.0s; }
                .wave-dot:nth-child(3) { animation-delay: -0.9s; }
                .wave-dot:nth-child(4) { animation-delay: -0.8s; }
                .wave-dot:nth-child(5) { animation-delay: -0.7s; }
                
                @keyframes wave {
                    0%, 80%, 100% { transform: scale(0); }
                    40% { transform: scale(1); }
                }
            `}</style>

            {/* --- 1. HERO SECTION (Distinct "Directory" Look) --- */}
            <header style={styles.hero}>
                {/* LEFT: Branding & Icon */}
                <div className="d-flex align-items-center">
                    <div style={{
                        width: '60px', height: '60px',
                        background: '#000', color: '#fff',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: '1.8rem', marginRight: '20px',
                        boxShadow: '0 10px 20px rgba(0,0,0,0.15)'
                    }}>
                        <BsPersonBadge />
                    </div>
                    <div>
                        <h1 className="display-6 fw-bold mb-0" style={{ letterSpacing: '-1px' }}>PERSONNEL NEXUS</h1>
                        <p className="text-muted small mb-0 text-uppercase" style={{ letterSpacing: '2px' }}>
                            System V2.0 // Human Resources
                        </p>
                    </div>
                </div>

                {/* Visual Stats Block - Different from cards */}
                <div className="d-flex gap-5">
                    <div style={styles.statBlock}>
                        <div style={styles.statNum}>{stats.total}</div>
                        <div style={styles.statLabel}>Total Headcount</div>
                    </div>
                    <div style={styles.statBlock}>
                        <div style={styles.statNum}>{stats.admins}</div>
                        <div style={styles.statLabel}>Administrators</div>
                    </div>

                    {/* Mini Radial Chart for quick visual */}
                    <div style={{ width: '80px', height: '80px' }}>
                        <ResponsiveContainer>
                            <PieChart>
                                <Pie data={stats.roleData} innerRadius={25} outerRadius={40} dataKey="value" stroke="none">
                                    {stats.roleData.map((e, i) => <Cell key={i} fill={CHART_COLORS[i]} />)}
                                </Pie>
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </header>

            {/* --- 2. TOOLBAR --- */}
            <div style={styles.toolbar}>
                <div>
                    <button style={styles.backButton} onClick={() => handleTransition('/')}>← Back</button>
                </div>
                <div style={styles.searchContainer}>
                    <BsSearch style={styles.searchIcon} />
                    <input
                        type="text"
                        style={styles.searchInput}
                        placeholder="Search personnel by name or email..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>

                <div className="d-flex gap-2">
                    <button
                        className={`btn rounded-0 ${filterRole === 'ALL' ? 'btn-dark' : 'btn-outline-dark'}`}
                        onClick={() => setFilterRole('ALL')}>ALL</button>
                    <button
                        className={`btn rounded-0 ${filterRole === 'ADMIN' ? 'btn-dark' : 'btn-outline-dark'}`}
                        onClick={() => setFilterRole('ADMIN')}>ADMINS</button>
                    <button
                        className={`btn rounded-0 ${filterRole === 'USER' ? 'btn-dark' : 'btn-outline-dark'}`}
                        onClick={() => setFilterRole('USER')}>USERS</button>
                </div>

                <div className="ms-auto d-flex gap-2">
                    {/* GRID View Button */}
                    <button
                        className={`btn rounded-0 d-flex align-items-center gap-2 ${viewMode === 'grid' ? 'btn-dark' : 'btn-outline-dark'}`}
                        onClick={() => setViewMode('grid')}
                    >
                        <BsGrid />
                    </button>

                    {/* LIST View Button */}
                    <button
                        className={`btn rounded-0 d-flex align-items-center gap-2 ${viewMode === 'list' ? 'btn-dark' : 'btn-outline-dark'}`}
                        onClick={() => setViewMode('list')}
                    >
                        <BsListUl />
                    </button>

                    {/* Export Button (Admin Only) */}
                    {isAdmin && (
                        <button className="btn btn-dark rounded-0 d-flex align-items-center gap-2" onClick={() => handleTransition(generatePDF)}>
                            <BsDownload /> EXPORT
                        </button>
                    )}
                </div>
            </div>

            {/* --- 3. CONTENT AREA --- */}
            <div className="container-fluid px-4 pb-5">

                {/* VIEW: GRID (ID CARDS) */}
                {viewMode === 'grid' && (
                    <div className="row g-4">
                        {paginatedUsers.map(user => (
                            <div className="col-xl-3 col-lg-4 col-md-6" key={user.id}>
                                <div style={styles.idCard}>
                                    <div style={styles.idHeader}>
                                        {/* Optional: Add a pattern or logo to the black header */}
                                        <div style={{ position: 'absolute', right: '10px', top: '10px', color: 'rgba(255, 255, 255, 0.4)' }}>
                                            <BsShieldLock size={20} />
                                        </div>
                                    </div>
                                    <div style={styles.idAvatarContainer}>
                                        <img src={getAvatar(user)} style={styles.idAvatar} alt="Avatar" />
                                    </div>
                                    <div style={styles.idBody}>
                                        <div style={styles.idName}>{user.firstname} {user.lastname}</div>
                                        <span style={{
                                            ...styles.idRole,
                                            background: (user.type || '').toLowerCase() === 'admin' ? '#000' : '#f4f4f5',
                                            color: (user.type || '').toLowerCase() === 'admin' ? '#fff' : '#000'
                                        }}>
                                            {user.type || 'User'}
                                        </span>
                                        <div style={styles.idMeta}><BsEnvelope size={12} /> {user.email}</div>
                                        <div style={styles.idMeta}><BsTelephone size={12} /> {user.phone || 'N/A'}</div>
                                    </div>
                                    <div style={styles.idActions}>
                                        <BsEye style={styles.actionIcon} onClick={() => setSelectedUser(user)} title="View Dossier" />
                                        {/*{(isAdmin) && (
                                            <BsPencil style={styles.actionIcon} onClick={() => navigate(`/update-profile/${user.id}`)} title="Edit Profile" />
                                        )}*/}
                                        {isAdmin && (
                                            <BsTrash style={{ ...styles.actionIcon, color: '#dc2626' }} onClick={() => initiateDelete(user)} title="Revoke Access" />
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {/* VIEW: LIST (CONTACT STRIPS) */}
                {viewMode === 'list' && (
                    <div>
                        {paginatedUsers.map(user => (
                            <div key={user.id} style={styles.listRow}>
                                <div className="d-flex align-items-center gap-3" style={{ flex: 2 }}>
                                    <img src={getAvatar(user)} style={{ width: '40px', height: '40px', borderRadius: '50%', objectFit: 'cover' }} alt="av" />
                                    <div>
                                        <div className="fw-bold">{user.firstname} {user.lastname}</div>
                                        <div className="small text-muted">#{user.userid}</div>
                                    </div>
                                </div>
                                <div style={{ flex: 2 }} className="text-muted small"><BsEnvelope className="me-2" />{user.email}</div>
                                <div style={{ flex: 1 }}>
                                    <span className="badge bg-light text-dark border">{user.type || 'User'}</span>
                                </div>
                                <div style={{ flex: 1 }} className="text-end">
                                    <button className="btn btn-sm btn-link text-dark" onClick={() => setSelectedUser(user)}>VIEW</button>
                                    {/*{(isAdmin) && (
                                        <button className="btn btn-sm btn-link text-primary" onClick={() => navigate(`/update-profile/${user.id}`)}>EDIT</button>
                                    )}*/}
                                    {isAdmin && (
                                        <button className="btn btn-sm btn-link text-danger" onClick={() => initiateDelete(user)}>DELETE</button>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {/* Pagination */}
                <div className="d-flex justify-content-center mt-5 gap-2">
                    <button className="btn btn-outline-dark btn-sm rounded-0" disabled={currentPage === 1} onClick={() => handleTransition(() => setCurrentPage(p => p - 1))}>PREVIOUS</button>
                    <span className="btn btn-light btn-sm rounded-0 disabled">Page {currentPage} of {totalPages}</span>
                    <button className="btn btn-outline-dark btn-sm rounded-0" disabled={currentPage === totalPages} onClick={() => handleTransition(() => setCurrentPage(p => p + 1))}>NEXT</button>
                </div>
            </div>

            {/* --- 4. DOSSIER MODAL (The "Premium Popup") --- */}
            {selectedUser && (
                <div style={styles.modalOverlay} onClick={() => setSelectedUser(null)}>
                    <div style={styles.dossier} onClick={e => e.stopPropagation()}>

                        {/* Dark Sidebar */}
                        <div style={styles.dossierSidebar}>
                            <img
                                src={getAvatar(selectedUser)}
                                style={{ width: '120px', height: '120px', borderRadius: '50%', border: '4px solid rgba(255,255,255,0.1)', marginBottom: '1.5rem', objectFit: 'cover' }}
                                alt="Profile"
                            />
                            <h3 className="mb-1">{selectedUser.firstname}</h3>
                            <h4 className="fw-light opacity-75">{selectedUser.lastname}</h4>
                            <div className="mt-4 w-100 pt-4 border-top border-secondary">
                                <div className="small text-uppercase opacity-50 mb-1">System Role</div>
                                <div className="badge bg-white text-dark w-100 py-2">{selectedUser.type || 'Standard User'}</div>
                            </div>
                        </div>

                        {/* White Content Area */}
                        <div style={styles.dossierContent}>
                           {/* <span className="badge bg-dark mb-2 rounded-0">ACTIVE</span> */}
                            <div className="d-flex justify-content-between align-items-center mb-5">
                                <h5 className="text-uppercase letter-spacing-1 fw-bold border-bottom pb-2">#{selectedUser.userid}</h5>
                                <BsPersonBadge size={24} className="text-muted" />
                            </div>

                            <div className="row g-4">
                                <div className="col-12">
                                    <label className="small text-muted text-uppercase fw-bold">Contact Email</label>
                                    <div className="fs-5">{selectedUser.email}</div>
                                </div>
                                <div className="col-6">
                                    <label className="small text-muted text-uppercase fw-bold">Phone</label>
                                    <div className="fs-6">{selectedUser.phone || 'Not Registered'}</div>
                                </div>
                                <div className="col-6">
                                    <label className="small text-muted text-uppercase fw-bold">Location</label>
                                    <div className="fs-6">{selectedUser.address || 'Unknown'}</div>
                                </div>
                                <div className="col-12 mt-4">
                                    <div className="p-3 bg-light border rounded-0 d-flex align-items-center gap-3">
                                        <BsShieldLock size={20} />
                                        <div>
                                            <div className="fw-bold small">SECURITY CLEARANCE</div>
                                            <div className="small text-muted">Account is active and verified.</div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="mt-auto pt-5 d-flex justify-content-end">
                                <button className="btn btn-dark rounded-0 px-4" onClick={() => setSelectedUser(null)}>CLOSE FILE</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- 🔒 SECURITY CHALLENGE MODAL (NEW) --- */}
            {deleteTarget && (
                <div style={styles.modalOverlay} onClick={() => setDeleteTarget(null)}>
                    <div style={styles.securityBox} onClick={e => e.stopPropagation()}>
                        {/* Red Header */}
                        <div style={styles.securityHeader}>
                            <BsExclamationTriangleFill size={30} />
                            <div>
                                <h4 className="m-0 fw-bold">SECURITY PROTOCOL</h4>
                                <small className="opacity-75">REVOKING PERSONNEL ACCESS</small>
                            </div>
                        </div>
                        
                        {/* Body */}
                        <div style={styles.securityBody}>
                            <p className="text-muted mb-4">
                                You are about to permanently delete the profile for <strong>{deleteTarget.firstname} {deleteTarget.lastname}</strong>. 
                                This action cannot be undone.
                            </p>

                            <div className="mb-4">
                                <label className="form-label small text-danger fw-bold">ENTER MASTER ADMIN KEY</label>
                                <input 
                                    type="password" 
                                    style={styles.securityInput} 
                                    placeholder="••••••••••"
                                    autoFocus
                                    value={securityCode}
                                    onChange={(e) => setSecurityCode(e.target.value)}
                                />
                                {securityError && <div className="text-danger small mt-2 fw-bold">{securityError}</div>}
                            </div>

                            <div className="d-flex gap-2">
                                <button className="btn btn-outline-secondary w-50 rounded-0 py-2" onClick={() => setDeleteTarget(null)}>CANCEL</button>
                                <button className="btn btn-danger w-50 rounded-0 py-2 fw-bold" onClick={confirmDelete}>CONFIRM REVOKE</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- ANIMATION OVERLAY --- */}
            {isNavigating && (
                <div style={styles.loaderOverlay}>
                    <div className="wave-loader">
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                    </div>
                    <div className="mt-4 text-dark small fw-bold text-uppercase" style={{letterSpacing: '2px'}}>Processing Request</div>
                </div>
            )}
        </div>
    );
}

export default DisplayUsers;